#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 100

int cmp(const void *a, const void *b) {
    int *A = (int *) a;
    int *B = (int *) b;
    return A[0] - B[0];
}

int main() {
    int minAverageLost;
    scanf("%d", &minAverageLost);

    int nums[MAX_SIZE];
    int nums_size = 0;

    while (scanf("%d", &nums[nums_size++])) {
        if (getchar() != ' ') break;
    }

    int preSum[nums_size + 1];
    preSum[0] = 0;

    for (int i = 1; i <= nums_size; i++) {
        preSum[i] = preSum[i - 1] + nums[i - 1];
    }

    int arrList[MAX_SIZE][2];
    int arrList_size = 0;

    int maxLen = 0;
    for (int i = 0; i < nums_size; i++) {
        for (int j = i + 1; j <= nums_size; j++) {
            // sum 是 区间 [i, j-1] 的和
            int sum = preSum[j] - preSum[i];
            int len = j - i;
            int lost = len * minAverageLost;

            if (sum <= lost) {
                if (len >= maxLen) {
                    if (len > maxLen) {
                        arrList_size = 0;
                    }
                    arrList[arrList_size][0] = i;
                    arrList[arrList_size][1] = j - 1;
                    arrList_size++;
                    maxLen = len;
                }
            }
        }
    }

    if (arrList_size == 0) {
        puts("NULL");
    } else {
        qsort(arrList, arrList_size, sizeof(int *), cmp);

        char res[10000];
        for (int i = 0; i < arrList_size; i++) {
            char tmp[100];
            sprintf(tmp, "%d-%d", arrList[i][0], arrList[i][1]);
            strcat(res, tmp);
            strcat(res, " ");
        }

        res[strlen(res) - 1] = '\0';

        puts(res);
    }

    return 0;
}
